private void permuteUtils(int[] array, int start, List<Integer> path, List<List<Integer>> result) {
        if (start == array.length) {
            result.add(new ArrayList<>(path));
            return;
        }

        for (int i = start; i < array.length; i++) {
            Collections.swap(array, start, i);
            path.add(array[start]);
            permuteUtils(array, start + 1, path, result);
            path.remove(path.size() - 1);
            Collections.swap(array, start, i);
        }
    }

