public List<List<Integer>> permute(int[] nums) {
    ArrayList<List<Integer>> result = new ArrayList<>();
    // Sort the array to make it easier to find permutations
    Arrays.sort(nums);
    backtrack(result, new ArrayList<>(Arrays.asList(nums)), 0);
    return result;
}

private void backtrack(List<List<Integer>> result, List<Integer> tempList, int start) {
    // Base case: if the list size is equal to the length of the array, add it to the result
    if (tempList.size() == nums.length) {
        result.add(new ArrayList<>(tempList));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        // Check if adding the current number to the list would result in a duplicate
        if (i > start && nums[i] == nums[i - 1]) {
            continue;
        }
        // Perform backtracking by adding the current number to the list
        tempList.add(nums[i]);
        // Recur with the updated list
        backtrack(result, tempList, i + 1);
        // Backtrack by removing the last added number
        tempList.remove(tempList.size() - 1);
    }
}

