public static int longestSubsequenceLength(String str1, String str2) {
        int m = str1.length();
        int n = str2.length();

        // Create a 2D array to store lengths of longest common subsequences
        int[][] dp = new int[m + 1][n + 1];

        // Build the dp array in bottom-up manner
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // The length of the longest common subsequence is in dp[m][n]
        return dp[m][n];
    }

