private static void markVisited(char[][] grid, int row, int col) {
    if (row >= 0 && row < grid.length && col >= 0 && col < grid[0].length && grid[row][col] == '*') {
        grid[row][col] = 'V'; // Mark the cell as visited
        markVisited(grid, row - 1, col); // Check above
        markVisited(grid, row + 1, col); // Check below
        markVisited(grid, row, col - 1); // Check left
        markVisited(grid, row, col + 1); // Check right
    }
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    Set<String> visited = new HashSet<>();
    int count = 0;

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@' && !visited.contains(getIndex(i, j)))) {
                count++;
                DFS(grid, i, j, visited);
            }
        }
    }

    return count;
}

private static String getIndex(int x, int y) {
    return x + "," + y;
}

private static void DFS(char[][] grid, int x, int y, Set<String> visited) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] == '*' || visited.contains(getIndex(x, y))) {
        return;
    }

    visited.add(getIndex(x, y));
    DFS(grid, x + 1, y, visited);
    DFS(grid, x - 1, y, visited);
    DFS(grid, x, y + 1, visited);
    DFS(grid, x, y - 1, visited);
}

