    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                exploreOil(grid, i, j);
            }
        }
    }
    return count;
}

private static void exploreOil(char[][] grid, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] != '@') {
        return;
    }
    grid[x][y] = '0'; // Mark as visited
    exploreOil(grid, x - 1, y); // Up
    exploreOil(grid, x, y - 1); // Left
    exploreOil(grid, x + 1, y); // Down
    exploreOil(grid, x, y + 1); // Right
}

