    if (!isStartClicked || !isEndClicked) {
        return "cannot be travelled";
    }

    // Check for cycles in the graph
    // Use DFS to detect cycles
    boolean[] visited = new boolean[n];
    for (int v = 0; v < n; v++) {
        if (visited[v]) {
            continue;
        }
        if (hasCycle(v, visited, new boolean[n], paths)) {
            return "cannot be travelled";
        }
    }

    // If no cycles are found, the path is possible
    return "can be travelled";
}

