public static String appx(String word1, String word2) {
    int commonCount = 0;
    for (char c1 : word1.toCharArray()) {
        for (char c2 : word2.toCharArray()) {
            if (c1 == c2) {
                commonCount++;
                break;
            }
        }
    }

    int numerator = commonCount;
    int denominator = word1.length() + word2.length() - commonCount;
    int gcd = gcd(numerator, denominator);

    numerator /= gcd;
    denominator /= gcd;

    return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
}

public static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

static String appx(String word1, String word2) {
    String commonChars = "";
    int commonCount = 0;
    int word1Length = word1.length();
    int word2Length = word2.length();

    for (int i = 0; i < word1Length && i < word2Length; i++) {
        char char1 = word1.charAt(i);
        char char2 = word2.charAt(i);

        if (char1 == char2) {
            commonChars += char1;
            commonCount++;
        }
    }

    if (commonCount == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int numerator = commonCount;
    int denominator = word1Length + word2Length;

    // Reduce the fraction to its simplest form
    boolean reduced = false;
    for (int i = 2; i <= Math.min(numerator, denominator); i++) {
        if ((numerator % i == 0) && (denominator % i == 0)) {
            numerator /= i;
            denominator /= i;
            i = 2;
            reduced = true;
        }
    }

    if (!reduced) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + (int)numerator + "/" + (int)denominator;
}

