public double trimMean(int[] arr) {
    double sortedAvg;
    int size = arr.length;

    int newLength = (int) Math.floor(0.05 * size);
    int start = newLength;

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the sum of the surviving elements
    double sum = 0;
    for (int i = start; i < size - newLength; i++) {
        sum += arr[i];
    }

    // Calculate the average of the surviving elements
    sortedAvg = sum / (size - 2 * newLength);

    return sortedAvg;
}

