public boolean canArrange(int[] arr, int k) {
    int[] modCount = new int[k];
    for (int num : arr) {
        modCount[num % k]++;
    }

    if (k == 1 && modCount[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i < k; i++) {
        if (modCount[i] != modCount[k - i]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Count the remainders of the array elements when divided by k
    int[] remainderCounts = new int[k];
    for (int num : arr) {
        remainderCounts[num % k]++;
    }

    for (int i = 1; i < k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false;
        }
    }

    // Check for the last pair (if the number of elements is odd)
    if (k % 2 != 0) {
        remainderCounts[k / 2] = (remainderCounts[k / 2] % 2 == 0) ? remainderCounts[k / 2] : remainderCounts[k / 2] - 1;
    }

    return remainderCounts[k / 2] == 0;
}

public boolean canArrange(int[] arr, int k) {
    int len = arr.length;
    int mod[] = new int[k];
    for (int i = 0; i < len; i++) {
        int remainder = arr[i] % k;
        mod[remainder]++;
    }
    for (int i = 1; i < k / 2; i++) {
        if (mod[i] != mod[k - i]) {
            return false;
        }
    }
    return mod[k / 2] % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
    Map<Integer, Integer> map = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        if (remainder == 0 || map.containsKey(k - remainder)) {
            return true;
        }
        map.put(remainder, map.getOrDefault(remainder, 0) + 1);
    }
    return false;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }
    int arrLen = arr.length;
    HashMap<Integer, Integer> map = new HashMap<>();
    for (int val : arr) {
        val = val % k;
        map.put(val, 1 + map.getOrDefault(val, 0));
    }
    if (map.getOrDefault(0, 1) % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= arrLen / 2; i++) {
        if (map.get(k - i) == null || map.get(k - i) == 0) {
            return false;
        }
        map.put(k - i, map.get(k - i) - 1);
        map.put(i, map.get(i) - 1);
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Set<Integer> appleNodes = new HashSet<>();
        for (int i = 0; i < hasApple.length; i++) {
            if (hasApple[i]) {
                appleNodes.add(i);
            }
        }
        return minTime(n, edges, appleNodes, 0);
    }

private int minTime(int n, int[][] edges, HashSet<Integer> appleNodes, int node) {
        int totalTime = 0;
        for (int[] edge : edges) {
            if (edge[0] == node || edge[1] == node) {
                int childNode = edge[0] != node ? edge[1] : edge[0];
                if (appleNodes.contains(childNode)) {
                    totalTime += 2;
                } else {
                    totalTime += minTime(n, edges, appleNodes, childNode);
                }
            }
        }
        return totalTime;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    boolean[] visited = new boolean[n];
    int result = 0;
    traverse(0, graph, visited, hasApple, result);
    return result;
}

private int traverse(int node, List<List<Integer>> graph, boolean[] visited, boolean[] hasApple, int& result) {
    visited[node] = true;
    int time = 0;

    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            time += traverse(neighbor, graph, visited, hasApple, result);
        }
    }

    if (node == 0 && (time > 0 || hasApple[node])) {
        return time + 2; // Time to collect apples + time to return to node 0
    } else if (hasApple[node]) {
        return time + 2; // Time to collect apples
    } else {
        return 0; // No apples or no children, time stays the same
    }
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        int[] parent = new int[n];
        Arrays.fill(parent, -1);

        for (int[] edge : edges) {
            parent[edge[1]] = edge[0];
        }

        Queue<Integer> queue = new LinkedList<>();
        queue.offer(0);

        while (!queue.isEmpty()) {
            int node = queue.poll();

            for (int i = 0; i < n; i++) {
                if (parent[i] == node) {
                    queue.offer(i);
                }
            }

            if (hasApple[node]) {
                for (int i = 0; i < n; i++) {
                    if (parent[i] == node) {
                        hasApple[i] = false;
                    }
                }
            }
        }

        return hasApple[0] ? 0 : n - 1;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    return dfs(0, hasApple, graph, new boolean[n]);
}

private int dfs(int node, boolean[] hasApple, List<List<Integer>> graph, boolean[] visited) {
    if (visited[node]) {
        return 0;
    }

    visited[node] = true;

    int time = 0;
    for (int neighbor : graph.get(node)) {
        time += dfs(neighbor, hasApple, graph, visited);
    }

    if (node != 0 && (hasApple[node] || time > 0)) {
        time += 2;
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    int[] times = new int[n];
    boolean[] visited = new boolean[n];
    dfs(graph, hasApple, 0, times, visited);
    return times[0];
}

private int dfs(List<List<Integer>> graph, boolean[] hasApple, int node, int[] times, boolean[] visited) {
    visited[node] = true;
    int time = 0;

    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            time += dfs(graph, hasApple, neighbor, times, visited);
        }
    }

    if (hasApple[node] || time > 0) {
        times[node] = time + 1;
        return time + 2;
    }

    return 0;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);
    int[] counts = new int[26];

    // Count the occurrences of each character
    for (char c : s.toCharArray()) {
        counts[c - 'a']++;
        minHeap.offer(c);
        maxHeap.offer(c);
    }

    StringBuilder result = new StringBuilder();
    while (!minHeap.isEmpty()) {
        char minChar = minHeap.poll();
        count[s.indexOf(minChar)]--;

        if (count[s.indexOf(minChar)] > 0) {
            minHeap.offer(minChar);
        }

        result.append(minChar);
    }

    while (!maxHeap.isEmpty()) {
        char maxChar = maxHeap.poll();
        count[s.lastIndexOf(maxChar)]--;

        if (count[s.lastIndexOf(maxChar)] > 0) {
            maxHeap.offer(maxChar);
        }

        result.append(maxChar);
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    HashMap<Character, Integer> charFrequency = new HashMap<>();
    for (char c : s.toCharArray()) {
        charFrequency.put(c, charFrequency.getOrDefault(c, 0) + 1);
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        // Fill in steps from 1 to 6
        while (!charFrequency.isEmpty()) {
            char smallest = minChar(charFrequency);
            removeChar(s, smallest);
            result.append(smallest);
        }

        while (!charFrequency.isEmpty()) {
            char largest = maxChar(charFrequency);
            removeChar(s, largest);
            result.append(largest);
        }
    }

    return result.toString();
}

private char minChar(Map<Character, Integer> map) {
    return map.entrySet().stream()
                .min(Map.Entry.comparingByValue())
                .orElseThrow(() -> new IllegalArgumentException("No characters found"))
                .getKey();
}

private char maxChar(Map<Character, Integer> map) {
    return map.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .orElseThrow(() -> new IllegalArgumentException("No characters found"))
                .getKey();
}

private void removeChar(String s, char c) {
    int index = s.indexOf(c);
    while (index != -1) {
        s = s.substring(0, index) + s.substring(index + 1);
    }
}

public String sortString(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    List<Character>chars = new ArrayList<>(s.toCharArray());
    StringBuilder result = new StringBuilder();

    while (chars.size() > 0) {
        int minIndex = findMinIndex(chars);
        char minChar = chars.remove(minIndex);
        result.append(minChar);

        int maxIndex = findMaxIndex(chars);
        char maxChar = chars.remove(maxIndex);
        result.append(maxChar);
    }

    return result.toString();
}

private int findMinIndex(List<Character> chars) {
    int minIndex = 0;
    int minValue = chars.get(0);
    for (int i = 1; i < chars.size(); i++) {
        if (chars.get(i) < minValue) {
            minIndex = i;
            minValue = chars.get(i);
        }
    }
    return minIndex;
}

private int findMaxIndex(List<Character> chars) {
    int maxIndex = 0;
    int maxValue = chars.get(0);
    for (int i = 1; i < chars.size(); i++) {
        if (chars.get(i) > maxValue) {
            maxIndex = i;
            maxValue = chars.get(i);
        }
    }
    return maxIndex;
}

public String sortString(String s) {
    StringBuilder sortedString = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        int smallestIndex = findMinIndex(s, sortedString);
        int largestIndex = findMaxIndex(s, sortedString);

        if (smallestIndex != -1) {
            sortedString.append(s.charAt(smallestIndex));
        }

        if (largestIndex != -1) {
            sortedString.append(s.charAt(largestIndex));
        }
    }
    return sortedString.toString();
}

private int findMinIndex(String s, StringBuilder sortedString) {
    int minIndex = -1;
    int minChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (minChar > s.charAt(i) && !sortedString.toString().contains(Character.toString(s.charAt(i)))) {
            minChar = s.charAt(i);
            minIndex = i;
        }
    }
    return minIndex;
}

private int findMaxIndex(String s, StringBuilder sortedString) {
    int maxIndex = -1;
    int maxChar = s.charAt(s.length() - 1);

    for (int i = s.length() - 2; i >= 0; i--) {
        if (maxChar < s.charAt(i) && !sortedString.toString().contains(Character.toString(s.charAt(i)))) {
            maxChar = s.charAt(i);
            maxIndex = i;
        }
    }
    return maxIndex;
}

public String sortString(String s) {
   .PriorityQueue<Character> minHeap = new PriorityQueue<>();
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    for (char c : s.toCharArray()) {
        minHeap.offer(c);
        maxHeap.offer(c);
    }

    StringBuilder sortedString = new StringBuilder();

    while (!minHeap.isEmpty() || !maxHeap.isEmpty()) {
        // Append smallest character from minHeap
        if (!minHeap.isEmpty()) {
            sortedString.append(minHeap.poll());
        }

        // Append largest character from maxHeap if it is different from the first appended character or if the end of the list is reached
        if (!maxHeap.isEmpty() && (!sortedString.isEmpty() && maxHeap.peek() != sortedString.charAt(sortedString.length() - 1)) || maxHeap.peek() == minHeap.peek()) {
            sortedString.append(maxHeap.poll());
        }
    }

    return sortedString.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) return false;

    int targetSum = Arrays.stream(nums).sum();
    int leftSum = 0;
    int sum = 0;

    for (int i = 0; i < nums.length - 1; i++) {
        leftSum += nums[i];
        int remainingSum = targetSum - leftSum;

        if ( leftSum % 2 == 0 && remainingSum % 2 == 0 && leftSum / 2 == remainingSum / 2) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) return false;

    int n = nums.length;
    int totalSum = Arrays.stream(nums).sum();
    double targetSum = totalSum / 2.0;

    boolean[] seen = new boolean[totalSum + 1];
    seen[0] = true;

    for (int num : nums) {
        for (int i = totalSum; i >= num; i--) {
            if (seen[i - num]) {
                seen[i] = true;
            }
        }
    }

    return seen[totalSum] && totalSum <= n;
}

public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        int length = nums.length;
        double targetSum = totalSum / 2.0;

        for (int i = 1; i < length; i++) {
            if ((targetSum - nums[i]) % i == 0) {
                return true;
            }
        }

        return false;
    }

public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        int n = nums.length;

        // Check if the total sum is even and if n is odd
        if (totalSum % n != 0) return false;

        // Find the median sum that should be the average of both split arrays
        int medianSum = totalSum / n;

        // Helper function to check if there exists a subarray with sum equal to medianSum
        for (int i = 0; i < n; i++) {
            // Calculate the remaining sum required for the second array
            int remainingSum = totalSum - medianSum;
            int found = isSubset(nums, i + 1, remainingSum);
            if (found) return true;
        }

        // If no such subarray is found, return false
        return false;
    }

private boolean isSubset(int[] nums, int start, int target) {
        if (target == 0) return true;
        if (start >= nums.length || target < 0) return false;
        return (isSubset(nums, start + 1, target - nums[start]) ||
                isSubset(nums, start + 1, target));
    }

public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    double targetSum = totalSum / 2.0;

    return findSubsetWithTotal(nums, totalSum / 2, nums.length);
}

private boolean findSubsetWithTotal(int[] nums, double target, int index) {
    if (target == 0) {
        return true;
    }
    if (index == 0 || target < 0) {
        return false;
    }

    if (nums[index - 1] > target) {
        return findSubsetWithTotal(nums, target, index - 1);
    } else {
        return findSubsetWithTotal(nums, target - nums[index - 1], index - 1) || findSubsetWithTotal(nums, target, index - 1);
    }
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
        int n = cost.length;
        if (n == 0) return 0;
        if (n == 1) return cost[0];
        if (n == 2) return Math.min(cost[0], cost[1]);

        int[] dp = new int[n];
        dp[0] = cost[0];
        dp[1] = cost[1];

        for (int i = 2; i < n; i++) {
            dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
        }

        return dp[n-1];
    }

