public boolean hasAllCodes(String s, int k) {
    if (s.length() < k || s.substring(0, k) == "") return false;

    int count = (int) Math.pow(2, k);
    return count == s.length();
}

public static boolean hasAllCodes(String s, int k) {
        HashSet<String> seen = new HashSet<>();
        if (s.length() < k) return false;

        for (int i = 0; i <= s.length() - k; i++) {
            String sub = s.substring(i, i + k);
            if (seen.contains(sub)) {
                return false;
            }
            seen.add(sub);
        }

        return true;
    }

public boolean hasAllCodes(String s, int k) {
    Set<String> seen = new HashSet<>();
    int length = s.length() - k + 1;
    for (int i = 0; i < length; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
    }
    return seen.size() == 1 << k;
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < k || k == 0) return false;

    int[] count = new int[1024];
    for (int i = 0; i <= s.length() - k; i++) {
        count[s.charAt(i) - '0']++;
    }

    for (int i = 0; i < 1024; i++) {
        if (count[i] == 0) return false;
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
        HashSet<String> seen = new HashSet<>();
        int index = 0;
        for (; index < k && index < s.length(); index++) {
            seen.add(s.substring(index, index + k));
        }
        return s.length() >= k && seen.size() == 1 << k;
    }

