public int minInsertions(String s) {
    int balance = 0;
    int insertion = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (balance > 0) {
                balance--;
            } else {
                insertion++;
            }
        }
    }

    // Add extra parentheses needed to balance the string
    return -balance + insertion;
}

public int minInsertions(String s) {
        Stack<Character> stack = new Stack<>();

        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(c);
            } else {
                if (stack.isEmpty()) {
                    stack.push('(');
                    continue;
                }
                stack.pop();
            }
        }

        int inserts = stack.size();
        for (char c : s.toCharArray()) {
            if (c == ')') {
                if (stack.isEmpty()) {
                    inserts++;
                    continue;
                }
                stack.pop();
            }
        }

        return inserts;
    }

public int minInsertions(String s) {
    int n = s.length();
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')' && balance > 0) {
            balance--;
        } else {
            insertions++;
            balance++;
        }
    }

    // If balance is negative, it means there's an extra '('
    if (balance < 0) {
        insertions += -balance;
    }

    return insertions;
}

