    int balance = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else {
            if (balance == 0) {
                insertions++;
            } else {
                balance--;
            }
        }
    }

    return insertions + balance; // One extra insertion for each unmatched ')'
}

public int minInsertions(String s) {
    int balance = 0, insertions = 0, imbalance = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else {
            if (balance > 0) {
                balance--;
            } else {
                insertion++;
                imbalance++;
            }
        }
    }

    insertions += imbalance * 2; // Each imbalance contributes two insertion operations

    return insertions;
}

