public int maxAbsoluteSum(int[] nums) {
    if(nums.length == 0)
        return 0;

    int maxSum = nums[0], minSum = nums[0];
    int curMax = 0, curMin = 0;

    for(int i = 1; i < nums.length; i++) {
        curMax = Math.max(nums[i], curMax + nums[i]);
        curMin = Math.min(nums[i], curMin + nums[i]);

        maxSum = Math.max(maxSum, curMax);
        minSum = Math.min(minSum, curMin);
    }

    return Math.max(maxSum, -minSum);
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = Integer.MIN_VALUE;
    int minSum = Integer.MAX_VALUE;

    for (int num : nums) {
        maxSum = Math.max(maxSum + num, num);
        minSum = Math.min(minSum + num, num);
        maxSum = Math.max(maxSum, 0);
        minSum = Math.min(minSum, 0);
    }

    return Math.max(maxSum, -minSum);
}

public int maxAbsoluteSum(int[] nums) {
        int maxsum = nums[0];
        int minsum = nums[0];
        int curSum = nums[0];
        int maxAbs = nums[0];

        for(int i=1; i<nums.length; i++) {
            curSum = Math.max(nums[i], curSum + nums[i]);
            curSum = Math.min(nums[i], curSum + nums[i]);
            maxsum = Math.max(maxsum, curSum);
            minsum = Math.min(minsum, curSum);
            maxAbs = Math.max(maxAbs, Math.abs(maxsum));
            maxAbs = Math.max(maxAbs, Math.abs(minsum));
        }

        return maxAbs;
}

public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    int maxSubSequenceSum = Arrays.stream(nums).max().getAsInt();
    int maxPrefixSum = 0;
    int minSuffixSum = 0;

    int maxAbsoluteSum = 0;
    for (int num : nums) {
        maxPrefixSum = Math.max(num, maxPrefixSum + num);
        minSuffixSum = Math.min(num, minSuffixSum + num);
        maxAbsoluteSum = Math.max(maxAbsoluteSum, maxSubSequenceSum);
        maxAbsoluteSum = Math.max(maxAbsoluteSum, Math.abs(minSuffixSum));
    }

    return maxAbsoluteSum;
}

