}

public int findMinFibonacciNumbers(int k) {
    int[] fibNums = {1, 1, 2, 3, 5, 8, 13, 21};
    int count = 0;
    int i = fibNums.length - 1;

    while (k > 0) {
        if (k >= fibNums[i]) {
            k -= fibNums[i];
            count++;
        }
        i--;
    }

    return count;
