        fibonacci.add((long) 1);
        fibonacci.add((long) 1);
        long next = 2;
        while (next <= k) {
            fibonacci.add(next);
            next = fibonacci.get(fibonacci.size() - 1) + fibonacci.get(fibonacci.size() - 2);
        }
       Collections.sort(fibonacci, Collections.reverseOrder());

        int count = 0;
        int index = fibonacci.size() - 1;
        while (k > 0 && index >= 0) {
            if (k - fibonacci.get(index) >= 0) {
                k -= fibonacci.get(index);
