public int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return k;
    }

    int a = 1; // 初始化第一个斐波那契数
    int b = 1; // 初始化第二个斐波那契数
    int count = 0; // 初始化计数器

    // 迭代找出最大不超过 k 的斐波那契数
    while (a + b <= k) {
        int temp = a + b;
        a = b;
        b = temp;
        count++;
    }

    // 从斐波那契数列中找出模 k 的余数
    int mod = k % a;

    // 将模 mod 的余数加到斐波那契数列中， repeating此过程直到模 mod 的余数为零
    while (mod != 0) {
        int temp = b;
        b = mod;
        mod = a % b;
        count++;
    }

    return count;
}

public static int findMinFibonacciNumbers(int k) {
    int[] fibNumbers = generateFibonacci(100); // Generate the first 100 Fibonacci numbers
    int count = 0, sum = 0;
    while (k > 0) {
        if (sum + fibNumbers[count] > k) {
            count--;
        } else {
            sum += fibNumbers[count];
        }
        count++;
    }
    return count - 1; // Subtract 1 because we are counting the last Fibonacci number we added
}

private static int[] generateFibonacci(int limit) {
    int[] fib = new int[limit];
    fib[0] = 0;
    if (limit >= 1) {
        fib[1] = 1;
    }
    for (int i = 2; i < limit; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    return fib;
}

