    int i = fib.length - 1;
    while (i >= 0 && fib[i] > k) {
        i--;
    }

    int count = 0;
    while (k > 0) {
        if (k - fib[i] >= 0) {
            k -= fib[i];
            count++;
        }
        i--;
    }

    return count;
}

