public String makeGood(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    Deque<Character> stack = new LinkedDeque<>();

    for (char c : s.toCharArray()) {
        if (stack.isEmpty() && c == Character.toUpperCase(stack.peek())) {
            stack.pop();
        } else if (!stack.isEmpty() && c == Character.toLowerCase(stack.peek())) {
            stack.pop();
        } else {
            stack.push(c);
        }
    }

    StringBuilder sb = new StringBuilder();
    while (!stack.isEmpty()) {
        sb.append(stack.pop());
    }

    return sb.reverse().toString();
}

