public String makeGood(String s) {
    int left = 0;
    int right = 0;

    while (right < s.length()) {
        if (left >= 0 && s.charAt(left - 1) == s.charAt(right)) {
            left--; // Remove adjacent characters
        } else {
            s = s.substring(0, left) + s.substring(right); // Add the current character to the result
            left = -1; // Reset left index to remove the last processed character
        }
        right++;
    }

    return s;
}

public int maxUniqueSplit(String s) {
