    Set<String> used = new HashSet<>();

    for (int i = 0; i < s.length(); i++) {
        while (i < s.length() && !used.contains(s.substring(i))) {
            used.add(s.substring(i));
            i++;
            count++;
        }
        maxCount = Math.max(maxCount, count);
        count = 0;
        used.clear();
    }

