public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n <= 1) {
        return n;
    }

    boolean[] visited = new boolean[n];
    int maxSplit = 0;

    for (int i = 0; i < n; i++) {
        Set<String> set = new HashSet<>();
        int start = i;
        while (start < n && !visited[start]) {
            visited[start] = true;
            set.add(s.substring(start, start + 1));
            maxSplit++;
            start++;
        }
    }

    return maxSplit;
}

public int maxUniqueSplit(String s) {
