        return s.length();
    }

    Set<String> uniqueSubstrings = new HashSet<>();
    int splitCount = 0;

    for (int i = 0; i < s.length(); i++) {
        if (!uniqueSubstrings.contains(String.valueOf(s.charAt(i)))) {
            uniqueSubstrings.add(String.valueOf(s.charAt(i)));
            splitCount++;
        }
        for (int j = i + 1; j < s.length(); j++) {
            if (!uniqueSubstrings.contains(String.valueOf(s.charAt(i)) + s.charAt(j)) {
                uniqueSubstrings.add(String.valueOf(s.charAt(i)) + s.charAt(j));
                splitCount++;
            } else {
                break;
            }
        }
    }

    return splitCount;
}

