public int minOperations(String[] logs) {
        int currentDepth = 0;

        for (String log : logs) {
            switch (log) {
                case "./":
                    continue;
                case "../":
                    if (currentDepth > 0) {
                        currentDepth--;
                    }
                    break;
                default:
                    currentDepth++;
            }
        }

        return currentDepth;
    }

public int findMinOperations(String[] logs) {
        int totalOperations = 0;
        int maxDepth = 0;
        int currentLevel = 0;

        for (String log : logs) {
            switch (log) {
                case "./":
                    currentLevel = 0;
                    break;
                case "../":
                    maxDepth = Math.max(maxDepth, currentLevel);
                    currentLevel = 0;
                    totalOperations = Math.max(totalOperations, currentLevel - maxDepth);
                    break;
                default:
                    currentLevel++;
                    totalOperations = Math.max(totalOperations, currentLevel - maxDepth);
            }
        }

        return totalOperations;
    }

