public String getSmallestString(int n, int k) {
    StringBuilder sequence = new StringBuilder(n);
    int lastMaxIndex = n - 1;
    int lastPosition = sequence.length();

    while (lastMaxIndex >= 0) {
        int nextMax = Math.min(lastPosition + 1, lastMaxIndex + 1 + k - lastMaxIndex * (lastPosition + 1));
        sequence.setCharAt(lastMaxIndex, (char) ('a' + lastMax - 1));
        k -= lastMax - 1;
        lastMax = nextMax;
        lastPosition--;
    }

    return sequence.toString();
}

