public static double calculateProbability(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Passenger count must be a positive integer.");
    }

    if (n <= 2) {
        return 1.0;
    }

    // The last passenger will sit in their own seat with probability 1/2
    // if they are in their own seat, or with probability 1/4 if they are not
    double probability = (1.0 / 2) * calculateProbability(n - 1) + (1.0 / 4) * calculateProbability(n - 2);

    return probability;
}

