public static int singleNumber(int[] nums) {
    int one = 0, two = 0, unset = 0;
    for (int num : nums) {
        two = ~(one & num) & two; // Remove common bits between one and num
        one = ~(two & num) & one; // Remove common bits between two and num
        unset = ~unset & num;    // Remove single bits in unset
    }
    return one; // The unset bit is the one that appears only once
}

public static int singleNumber(int[] nums) {
