public static List<Integer> findSteppingNumbers(int low, int high) {
        if (low < 0 || high < 0 || low > high) {
            return new ArrayList<>();
        }

        List<Integer> steppingNumbers = new ArrayList<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(0);

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                steppingNumbers.add(num);
            }
            if (num <= high) {
                int lastDigit = num % 10;
                if (lastDigit > 0) {
                    queue.offer(num * 10 + lastDigit - 1);
                }
                if (lastDigit < 9) {
                    queue.offer(num * 10 + lastDigit + 1);
                }
            }
        }

        Collections.sort(steppingNumbers);
        return steppingNumbers;
    }

