private static boolean isSteppingNumber(int num) {
    int nextNum = num + 1;
    while (nextNum <= high) {
        if (!isSteppingNumberHelper(num, nextNum)) {
            return false;
        }
        nextNum++;
    }

    return true;
}

private static boolean isSteppingNumberHelper(int num1, int num2) {
    while (num1 > 0) {
        if (Math.abs(num1 % 10 - num2 % 10) == 1) {
            num1 /= 10;
            num2 /= 10;
        } else {
            return false;
        }
    }
    return true;
}

