private static boolean isSteppingNumber(int num) {
    int lastDigit = 0;
    while (num > 0) {
        int digit = num % 10;
        if (digit < lastDigit - 1 || digit > lastDigit + 1) {
            return false;
        }
        lastDigit = digit;
        num /= 10;
    }
    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(0);

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num == 0) {
            queue.offer(1);
            queue.offer(2);
        } else {
            int lastDigit = num % 10;
            if (lastDigit > 0 && num + (lastDigit - 1) <= high) {
                queue.offer(num * 10 + (lastDigit - 1));
            }
            if (lastDigit < 9 && num + (lastDigit + 1) <= high) {
                queue.offer(num * 10 + (lastDigit + 1));
            }
        }
    }

    result.sort(Integer::compare);
    return result;
}

