public static int countDigitOne(int n) {
    if (n == 0) {
        return 0;
    }
    int leadingOnes = n / 10;
    int trailingOnes = n % 10;
    int hundredsOnes = leadingOnes / 10;
    int remainder = leadingOnes % 10;
    int trailingOnesCount = trailingOnes == 1 ? remainder : 10;
    int beforeOneCount = leadingOnes + 1;
    return leadingOnesCount * 1 + 10 * trailingOnesCount + beforeOneCount * countDigitOne(trailingOnes);
}

public static int countDigitOne(int n) {
    int count = 0;
    int powerOfTen = 1;

    while (n >= powerOfTen) {
        int nextPowerOfTen = powerOfTen * 10;
        int high = n / nextPowerOfTen;
        int middle = (n / powerOfTen) % 10;
        int low = n % powerOfTen;

        if (middle == 0) {
            count += high * powerOfTen;
        } else if (middle == 1) {
            count += high * powerOfTen + low + 1;
        } else {
            count += (high + 1) * powerOfTen;
        }

        powerOfTen *= 10;
    }

    return count;
}

public static int countDigitOne(int n) {
    int count = 0, power = 1;
    while (n >= power) {
        int higher = (n / (power * 10)) * power; // Number of times 1 appears in the higher digits
        int middle = (n / power) % 10; // Number of times 1 appears in the middle digits
        int lower = n % power; // Number of times 1 appears in the lower digits

        count += higher + (temp >= 2) * (power); // Add higher digits, add middle digits if temp >= 2, add lower digits
        count += middle == 1 ? lower + 1 : lower; // Add middle digits if temp is 1, add lower digits

        power *= 10; // Move to the next higher digit
    }
    return count;
}

public static int countDigitOne(int n) {
