private static int countOccurrence(int number, int digit) {
    if (number == 0) return 0;
    int lastDigit = number % 10;
    if (lastDigit == digit) {
        return 1 + countOccurrence(number / 10, digit) + countOccurrence(number / 10, digit + 1);
    } else {
        return countOccurrence(number / 10, digit);
    }
}

