public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = Integer.MIN_VALUE;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, longestLineVertical(mat, i, j));
                maxLength = Math.max(maxLength, longestLineHorizontal(mat, i, j));
                maxLength = Math.max(maxLength, longestLineDiagonal(mat, i, j));
                maxLength = Math.max(maxLength, longestLineAntiDiagonal(mat, i, j));
            }
        }
    }
    return maxLength;
}

private static int longestLineVertical(int[][] mat, int row, int col) {
