public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int row = mat.length;
    int col = mat[0].length;
    int maxLength = 0;

    // Check horizontal lines
    for (int i = 0; i < row; i++) {
        int count = 0;
        for (int j = 0; j < col; j++) {
            if (mat[i][j] == 0) {
                count = 0;
            } else {
                count++;
                maxLength = Math.max(maxLength, count);
            }
        }
    }

    // Check vertical lines
    for (int j = 0; j < col; j++) {
        int count = 0;
        for (int i = 0; i < row; i++) {
            if (mat[i][j] == 0) {
                count = 0;
            } else {
                count++;
                maxLength = Math.max(maxLength, count);
            }
        }
    }

    // Check diagonal lines (top-right to bottom-left)
    for (int i = 0, j = 0; i < row && j < col; i++, j++) {
        int count = 0;
        while (i < row && j < col && mat[i][j] == 1) {
            count++;
            i++;
            j++;
        }
        maxLength = Math.max(maxLength, count);
    }

    // Check anti-diagonal lines (top-left to bottom-right)
    for (int i = 0, j = col - 1; i < row && j >= 0; i++, j--) {
        int count = 0;
        while (i < row && j >= 0 && mat[i][j] == 1) {
            count++;
            i++;
            j--;
        }
        maxLength = Math.max(maxLength, count);
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[] dp = new int[n];
    int[] dpDown = new int[n];
    int[] dpLeft = new int[n];
    int[] dpAnti = new int[n];

    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[j] = 1;
                dpDown[j] = (j > 0) ? dpDown[j - 1] + 1 : 1;
                dpLeft[j] = (j > 0) ? dpLeft[j - 1] + 1 : 1;
                dpAnti[j] = (i > 0 || j > 0) ? dpAnti[j - 1] + 1 : 1;

                maxLength = Math.max(maxLength, Math.max(dp[j], Math.max(dpDown[j], Math.max(dpLeft[j], dpAnti[j]))));
            }
        }
    }
    return maxLength;
}

public static String addThousandSeparator(int n) {
    // Convert the integer to a string
    String str = n.toString();

    // Extract the length of the string
    int length = str.length();

    // Initialize the result StringBuilder
    StringBuilder result = new StringBuilder();

    // Iterate through the string in chunks of three characters
    for (int i = 0; i < length; i += 3) {
        // Extract the next chunk of three characters
        String chunk = str.substring(i, Math.min(length, i + 3));

        // If this is the last chunk, add it to the result without a comma
        if (i == length - 3) {
            result.append(chunk);
        } else {
            // Add the chunk to the result with a comma
            result.append(chunk).append(".");
        }
    }

    // Return the final result string
    return result.toString();
}

public static String addThousandSeparator(int n) {
        StringBuilder sb = new StringBuilder();
        int count = 0;

        do {
            sb.insert(0, n % 1000);
            sb.insert(0, '.');
            count++;
            n /= 1000;
        } while (n > 0);

        return sb.toString().startsWith(".") ? sb.substring(1) : sb.toString();
    }

public static String addThousandSeparator(int n) {
    String numberString = Integer.toString(n);
    StringBuilder result = new StringBuilder();

    for (int i = numberString.length() - 3; i > 0; i -= 3) {
        result.insert(0, "..");
    }

    if (numberString.length() % 3 == 0) {
        result.insert(0, "..");
    }

    return result.toString() + numberString;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder sb = new StringBuilder();
    while (n > 0) {
        sb.insert(0, n % 1000);
        n /= 1000;
    }

    return sb.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (n > 0) {
        int digit = n % 10;
        sb.append(digit);
        i++;
        if (i % 3 == 0 && i < 4) {
            sb.append('.');
        } else if (i == 4 && n == 0) {
            sb.append('.');
        }
        n /= 10;
    }
    sb.reverse();
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;

    int result = 0;

    helper(A, n, 0, result);

    return result;
}

private static void helper(int[] A, int n, int i, int result) {
    if (i == n - 1) {
        if (A[i] * A[i] == A[i - 1])
            result++;
        return;
    }

    for (int j = i; j < n; j++) {
        if (A[j] < A[i])
            continue;

        swap(A, i, j);
        helper(A, n, i + 1, result);
        swap(A, i, j);
    }
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n % 2 != 0) {
        return 0;
    }

    int[] count = new int[100];
    int total = 1;

    for (int num : A) {
        count[num]++;
        if (Math.sqrt(num) % 1 == 0) {
            total *= count[(int)Math.sqrt(num)];
        } else {
            total = 0;
            break;
        }
    }

    return total;
}

public static int squarePermutations(int[] A) {
    int N = A.length;
    boolean[] visited = new boolean[N];
    return countSquarePermutations(A, 0, visited);
}

private static int countSquarePermutations(int[] A, int start, boolean[] visited) {
    if (start == A.length) {
        return 1;
    }

    int count = 0;

    for (int i = 0; i < N; i++) {
        if (!visited[i] && isValid(A, start, i)) {
            visited[i] = true;
            count += countSquarePermutations(A, start + 1, visited);
            visited[i] = false;
        }
    }

    return count;
}

private static boolean isValid(int[] A, int start, int end) {
    int sum = A[start] + A[end];
    return Math.sqrt(sum) % 1 == 0;
}

