public static int squarePermutations(int[] A) {
    int len = A.length;
    int count = 0;
    for (int i = 0; i < len; i++) {
        for (int j = i + 1; j < len; j++) {
            if (Math.sqrt(A[i] + A[j]) % 1 == 0) {
                count++;
                // Swap to break the pair
                int temp = A[i];
                A[i] = A[j];
                A[j] = temp;
            }
        }
    }
    return count;
}

public static int largestRectangleArea(int[] heights) {
        int maxArea = 0;
        int n = heights.length;

        for(int i = 0; i < n; i++) {
            int height = heights[i];
            int width = 1;

            // If the next bar is taller, expand the width of the rectangle
            for(int j = i + 1; j < n && heights[j] >= height; j++){
                width++;
            }

            // Calculate the area of the rectangle with the current height
            int area = height * width;

            // Update maxArea if the current area is greater
            if(area > maxArea) {
                maxArea = area;
            }
        }

        return maxArea;
    }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];
    Stack<Integer> stack = new Stack<>();

    // Find the left smallest element for each bar
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        leftSmaller[i] = stack.isEmpty() ? 0 : stack.peek() + 1;
        stack.push(i);
    }

    // Empty the stack
    while (!stack.isEmpty()) {
        stack.pop();
    }

    // Find the right smallest element for each bar
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        rightSmaller[i] = stack.isEmpty() ? heights.length - 1 : stack.peek() - 1;
        stack.push(i);
    }

    // Calculate the area for each bar and update maxArea
    for (int i = 0; i < heights.length; i++) {
        int height = heights[i];
        int width = rightSmaller[i] - leftSmaller[i] + 1;
        maxArea = Math.max(maxArea, height * width);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
        if (heights == null || heights.length == 0) return 0;

        Stack<Integer> stack = new Stack<>();
        int maxArea = 0;

        for (int i = 0; i <= heights.length; i++) {
            while (!stack.isEmpty() && (i == heights.length || heights[stack.peek()] > heights[i])) {
                int height = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, height * width);
            }
            stack.push(i);
        }

        return maxArea;
    }

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];

    calculateLeftSmaller(heights, leftSmaller);
    calculateRightSmaller(heights, rightSmaller);

    for (int i = 0; i < heights.length; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = width * heights[i];
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

private static void calculateLeftSmaller(int[] heights, int[] leftSmaller) {
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < heights.length; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        leftSmaller[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }
}

private static void calculateRightSmaller(int[] heights, int[] rightSmaller) {
    Stack<Integer> stack = new Stack<>();
    for (int i = heights.length - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        rightSmaller[i] = stack.isEmpty() ? heights.length : stack.peek();
        stack.push(i);
    }
}

public static int largestRectangleArea(int[] heights) {
    int area = 0;
    int i = 0;

    while(i + 1 < heights.length) {
        if(heights[i + 1] >= heights[i]) {
            i++;
            continue;
        }

        int width = i + 1;
        int j = i;

        while(j - 1 >= 0 && heights[j - 1] >= heights[i]) {
            width++;
            j--;
        }

        int height = heights[i];
        area = Math.max(area, height * width);
        i = j;
    }

    return area;
}

public static int[] diagonalOrder(int[][] mat) {
    int[][] directions = new int[][]{{+1, 0}, {-1, +1}};
    int d = 0;       // Direction index, 0: right, 1: down, 2: left, 3: up
    int x = 0, y = 0;  // Starting point coordinates
    int len = mat.length * mat[0].length;
    int[] result = new int[len];

    for (int c = 0; c < len; c++) {
        result[c] = mat[x][y];
        // Determine the next direction
        x += directions[d][0];
        y += directions[d][1];

        // Check for boundaries
        if (x >= mat.length || x < 0) {
            // Change direction if necessary
            d = (d + 1) % 4;
            // Adjust coordinates to start new diagonal
            x = d == 0 ? y + 1 : x - 1;
            y = d == 3 || d == 1 ? x + 1 : y - 1;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] visited = new int[m][n];

    List<Integer> output = new ArrayList<>();
    int row = 0, col = 0;

    while(row < m && col < n) {
        // Traverse up
        while(col >= 0 && !visited[row][col]) {
            output.add(mat[row][col]);
            visited[row][col] = 1;
            row--;
            col++;
        }
        row++; // Move down

        // Traverse left
        while(row < m && !visited[row][col]) {
            output.add(mat[row][col]);
            visited[row][col] = 1;
            row++;
            col--;
        }
        col++; // Move right
    }

    int[] result = new int[output.size()];
    for(int i = 0; i < output.size(); i++) {
        result[i] = output.get(i);
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[]{}; // Return an empty array if the input matrix is null or has no elements
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] res = new int[rows * cols]; // Create a result array to store the diagonal order elements

    int r = 0; // Initialize the row pointer
    int c = 0; // Initialize the column pointer

    boolean dir = true; // Initialize the direction of traversal as right to left

    for(int x = 0; x < res.length; x++) {
        res[x] = mat[r][c]; // Store the current element in the result array
        r += (dir ? -1 : 1); // Update the row pointer according to the current direction
        c += (dir ? 1 : -1); // Update the column pointer according to the current direction

        // Check if the current position is already processed or out of bounds
        if(r < 0 || c < 0 || r >= rows || c >= cols) {
            dir = !dir; // Change the direction
            r += (dir ? -1 : 1); // Move to the opposite direction
            if(dir) // Move to the first column if going from bottom to top
                c = 0;
            else // Move to the last row if going from top to bottom
                c = cols - 1;
        }
    }

    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int diagonal = 0; diagonal < rows + cols - 1; diagonal++) {
        int row = 0;
        int col = diagonal;
        if (diagonal < rows) {
            row = diagonal;
        } else {
            col = rows - (diagonal - rows) + 1;
        }

        while (row < rows && col < cols) {
            result[index++] = mat[row][col];
            if (diagonal % 2 == 0) {
                row++;
                col++;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int downD OW = false;
    int leftToRight = false;
    int[] result = new int[mat.length * mat[0].length];
    int idCounter = 0;
    int row = 0;
    int col = 0;
    int n = mat.length;
    boolean[][] visited = new boolean[n][n];

    while(idCounter != mat.length * mat[0].length) {
        while(!visited[row][col]) {
            result[idCounter] = mat[row][col];
            if(downDOW) {
                if(col + 1 < mat[0].length && !visited[row][col + 1]) {
                    col++;
                } else {
                    upDOW = true;
                    row++;
                }
            } else {
                if(row + 1 < mat.length && !visited[row + 1][col]) {
                    row++;
                } else {
                    downDOW = true;
                    col++;
                }
            }
            visited[row][col] = true;

            idCounter++;
        }

        upDOW = false;
        leftToRight = !leftToRight;

        if (downDOW && col + 1 < mat[0].length) {
            col++;
        } else if (!leftToRight && row + 1 < mat.length) {
            row++;
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n == 9) return -1;  // No integer can be formed by rearranging digits of 9.

    int[] digits = new int[4];  // Maximum 4 digits in a positive integer.
    int index = 0;

    while (n > 0) {
        digits[index++] = n % 10;
        n /= 10;
    }

    // Find the first digit from the end that is not 9.
    int i;
    for (i = index - 1; i >= 0; i--) {
        if (digits[i] != 9) {
            break;
        }
    }

    // If no such digit is found, then no integer can be formed.
    if (i == -1) return -1;

    // Swap the found digit with the smallest digit that is not equal to 9.
    for (; digits[i] == 9; i--) {
        // Replace the digit with the smallest non-9 digit found from the end.
        for (int j = index - 1; j >= i; j--) {
            if (digits[j] != 9) {
                digits[i] = digits[j];
                digits[j] = 9;
                break;
            }
        }
    }

    // Sort the remaining digits in ascending order.
    Arrays.sort(digits, 0, i + 1);

    // Form the new number by converting the array of digits back to an integer.
    int smallest = 0;
    for (int num : digits) {
        smallest = smallest * 10 + num;
    }

    return smallest;
}

public static int findSmallestInteger(int n) {
    while (true) {
        int temp = n;
        boolean found = false;

        // Try rotating the digits of n
        for (int i = 0; i < 9; i++) {
            temp = (temp % 10) * (int) Math.pow(10, 8 - i) + temp / 10;

            // Check if the rotated number is greater than n
            if (temp > n) {
                n = temp;
                found = true;
                break;
            }
        }

        if (!found) {
            return -1;
        }
    }
}

public static int findSmallestInteger(int n) {
    // Convert the input integer to a character array
    char[] digits = String.valueOf(n).toCharArray();

    // Perform an iterative selection sort starting from the second last digit to the first digit
    for (int i = digits.length - 2; i >= 0; i--) {
        int minIndex = i;
        for (int j = i + 1; j < digits.length; j++) {
            if (digits[j] < digits[minIndex]) {
                minIndex = j;
            }
        }
        // Swap the current digit with the smallest digit found so far
        char temp = digits[i];
        digits[i] = digits[minIndex];
        digits[minIndex] = temp;
    }

    // Convert the character array back to an integer
    int result = Integer.parseInt(new String(digits));

    // Check if the result is greater than the input integer and not equal to the input integer
    if (result > n && result != n) {
        return result;
    } else {
        return -1;
    }
}

public static int findSmallestInteger(int n) {
    if (n <= 1) return -1; // Single digit numbers cannot be rearranged to form a larger number

    // Convert number to array of digits
    int[] digits = new int[Integer.toString(n).length()];
    for (int i = 0; i < digits.length; i++) {
        digits[i] = n % 10;
        n /= 10;
    }

    // Sort the digits in ascending order
    Arrays.sort(digits);

    // Start from the largest digit and try to form the smallest number
    for (int i = digits.length - 1; i >= 0; i--) {
        if (digits[i] > digits[i - 1]) {
            // Swap the current digit with the smallest digit that is greater than it
            for (int j = digits.length - 1; j > i; j--) {
                if (digits[j] > digits[i]) {
                    Collections.swap(digits, i, j);
                    break;
                }
            }

            // Reverse the digits to form the smallest number
            reverse(digits);

            // Construct the smallest number from the array
            long smallest = 0;
            for (int digit : digits) {
                smallest = smallest * 10 + digit;
            }

            return (int) smallest;
        }
    }

    return -1; // No possible arrangement found
}

private static void reverse(int[] digits) {
    for (int i = 0, j = digits.length - 1; i < j; i++, j--) {
        Collections.swap(digits, i, j);
    }
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    Arrays.sort(digits);
    if (digits[0] == '0') return -1;

    for (int i = 0; i < digits.length; i++) {
        if (digits[i] == '9') continue;
        int temp = digits[i];
        digits[i] = digits[digits.length - 1];
        digits[digits.length - 1] = temp;
        char[] smallestInteger = String.valueOf(digits).toCharArray();
        if (Integer.parseInt(String.valueOf(smallestInteger)) > n) {
            return Integer.parseInt(String.valueOf(smallestInteger));
        }
    }

    return -1;
}

