public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbersList = new ArrayList<>();

    // Digits that can be used in the center symmetric numbers
    String digits = "0123456789";

    // Check if the length is less than or equal to 1
    if (n <= 1) {
        if (n == 1) {
            centerSymmetricNumbersList.add("0");
        }
        return centerSymmetricNumbersList;
    }

    // Generate the center symmetric numbers
    for (String str : generatePossibleNumbers(digits, n)) {
        String leftPart = str.substring(0, n/2);
        String rightPart = str.substring(n/2, n);
        String reversedRightPart = new StringBuilder(rightPart).reverse().toString();
        if (leftPart.equals(reversedRightPart)) {
            centerSymmetricNumbersList.add(str);
        }
    }

    return centerSymmetricNumbersList;
}

private static List<String> generatePossibleNumbers(String digits, int n) {
    List<String> possibleNumbers = new ArrayList<>();
    if (n == 1) {
        for (int i = 0; i < digits.length(); i++) {
            possibleNumbers.add(digits.charAt(i) + "");
        }
        return possibleNumbers;
    }

    // Generate numbers by considering the first half and constructing the rest
    for (int i = 0; i < digits.length(); i++) {
        List<String> subNumbers = generatePossibleNumbers(digits.substring(i + 1), n - 2);
        for (String num : subNumbers) {
            possibleNumbers.add(digits.charAt(i) + num);
        }
    }

    return possibleNumbers;
}

