public static List<String> centerSymmetricNumbers(int n) {
        if (n <= 0) {
            return new ArrayList<>();
        }

        Set<String> centerSymmetricNumbers = new HashSet<>();
        if (n == 1) {
            centerSymmetricNumbers.add("0");
        } else if (n == 2) {
            centerSymmetricNumbers.add("11");
            centerSymmetricNumbers.add("69");
        } else {
            int mid = n / 2;
            String prefix = "1" + createPattern(mid, "101");
            String suffix = new StringBuilder().append(createPattern(mid, "101")).reverse().toString();

            for (int i = 0; i < mid; i++) {
                String partial = createPattern(mid, "1" + createPattern(i, "01") + "0" + createPattern(i, "10"));
                centerSymmetricNumbers.add(prefix.substring(i) + partial + suffix.substring(mid - i - 1));
            }
        }

        return new ArrayList<>(centerSymmetricNumbers);
    }

private static String createPattern(int length, String pattern) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < length; i++) {
            sb.append(pattern);
        }
        return sb.toString();
    }

