public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("Array must contain three points.");
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Check for collinearity
    if ((y2 - y1) * (x3 - x2) == (x2 - x1) * (y3 - y2)) {
        return false;
    }

    // Check if the points form a boomerang
    return (y1 - y2) * (x3 - x2) * (y2 - y3) * (x2 - x3) > 0 ? true : false;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    return (y2 - y1) * (x3 - x2) != (y3 - y2) * (x2 - x1);
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the areas of the triangles formed by the points
    double area1 = area(x1, y1, x2, y2, x3, y3);
    double area2 = area(x1, y1, x3, y3, x2, y2);

    // If the areas are equal, the points are collinear and cannot form a boomerang
    return area1 != area2;
}

private static double area(int x1, int y1, int x2, int y2, int x3, int y3) {
    return 0.5 * Math.abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The input array must contain exactly 3 points.");
    }
    int[][] vector1 = new int[]{points[1][0] - points[0][0], points[1][1] - points[0][1]};
    int[][] vector2 = new int[]{points[2][0] - points[1][0], points[2][1] - points[1][1]};
    return (vector1[0] * vector2[1]) != (vector1[1] * vector2[0]);
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The input must contain exactly 3 points.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check the area of the triangle formed by the points
    // If the area is zero, the points are collinear
    // If the area is non-zero, the points form a boomerang
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    Queue<Long> q = new PriorityQueue<>();
    HashSet<Long> set = new HashSet<>();
    q.offer(1L);
    set.add(1L);
    int count = 0;
    long ugly = 0;

    while (true) {
        ugly = q.poll();
        set.remove(ugly);
        count++;
        if (count == n) {
            return (int) ugly;
        }
        q.offer(ugly * 2);
        q.offer(ugly * 3);
        q.offer(ugly * 5);
        set.add(ugly * 2);
        set.add(ugly * 3);
        set.add(ugly * 5);
    }
}

public static int findNthUglyNumber(int n) {
    int uglyCount = 0;
    int uglies[] = {1};
    int i2 = 0, i3 = 0, i5 = 0;

    while (uglyCount < n) {
        int minUgly = Math.min(uglies[i2] * 2, Math.min(uglies[i3] * 3, uglies[i5] * 5));
        uglies[uglyCount++] = minUgly;

        if (minUgly == uglies[i2] * 2) i2++;
        if (minUgly == uglies[i3] * 3) i3++;
        if (minUgly == uglies[i5] * 5) i5++;
    }

    return uglies[n - 1];
}

