public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }

    Set<Long> set = new HashSet<>();
    set.add(1L);

    int count = 1;
    while (count < n) {
        int prev = set.iterator().next();
        set.add(prev * 2);
        set.add(prev * 3);
        set.add(prev * 5);
        set.remove(prev);
        count++;
    }

    return set.iterator().next().intValue();
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxEnergy = 1, currentEnergy = 1;
    char lastChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == lastChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
        lastChar = s.charAt(i);
    }

    return Math.max(maxEnergy, currentEnergy);
}

