public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        addNumber(result, i);
    }
    return result;
}

private static void addNumber(List<Integer> result, int num) {
    result.add(num);
    while (num < 10) {
        num *= 10;
        if (num > n) {
            return;
        }
        result.add(num);
    }
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        int i = 1;
        while (i <= n) {
            result.add(i);
            i *= 10;
        }
        Collections.sort(result);
        return result;
    }

public static List<String> lexicalOrder(int n) {
        List<String> result = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        helper(n, sb, result);
        return result;
    }

private static void helper(int n, StringBuilder sb, List<String> result) {
        if (sb.length() > n) {
            return;
        }
        result.add(sb.toString());
        sb.append('1');
        helper(n, sb, result);
        sb.setLength(sb.length() - 1);
        if (sb.length() > 0) {
            sb.append('0');
            helper(n, sb, result);
            sb.setLength(sb.length() - 1);
        }
    }

