public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    for (int i = 1; i <= n; i++) {
        for (int j = j * j; j <= i; j++) {
            if ((i - j * j) % j == 0) {
                return (i - j * j) / j + 1;
            }
        }
    }
    return n;
}

